-- Real data behind casos.html / caso-<slug>.html, from Informe Final Innova Social 2026.

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'zoco-market', 'Zoco Market', 'Emilio Yaar · Fundador', 'Barranquilla',
  'Bioproductos y servicios sostenibles — Agroindustria sostenible', 'Zoco Market transforma materias primas de origen agrícola (legumbres, frutos secos, cereales) en alimentos de mínimo procesamiento y sin aditivos, y reduce el uso de empaques mediante su modelo de venta a granel; ambos rasgos corresponden a la subcategoría de agroindustria sostenible del Plan Nacional de Negocios Verdes.', 'c5',
  '+40% ventas', 'Multiplicó x4 su producción de hummus y abrió su propio centro de producción.', 'Zoco Market es un emprendimiento de comercio y transformación de alimentos saludables que opera en Barranquilla bajo un modelo de tienda física de experiencia, complementado con una línea propia de producción de alimentos horneados. Su portafolio combina productos elaborados en sitio —como hummus de garbanzo, mantequillas de maní, almendra y marañón, y una línea de galletas, postres y panes saludables— con la venta a granel de frutos secos, semillas, especias y otros insumos naturales, todos formulados sin aditivos ni conservantes artificiales. Atiende principalmente a hombres y mujeres adultos de Barranquilla que buscan una alimentación más consciente, y viene ampliando su alcance hacia clientes institucionales (hoteles, restaurantes, oficinas) y hacia canales de comercio electrónico.',
  10000000, 86041092, 120055808,
  '+40%', '["Adquisición de maquinaria (horno, batidora, cutter y mesón) y apertura de su propio centro de producción.", "Reducción del 84% en los tiempos y costos de producción de su producto estrella, el hummus de garbanzo, pasando de vender 15 a 60 unidades por semana.", "Creación de marca propia para una nueva línea de mantequillas (maní, almendras y marañón) y de galletas, postres y panes saludables.", "Desarrollo de estrategias de comercialización en canales digitales con alto impacto en la visibilidad de la marca."]'::jsonb, null, 1, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'la-mecedora-de-darwin', 'La Mecedora de Darwin', 'Federico Egea & J. Sebastián Rosero', 'Barranquilla',
  'Sin equivalencia exacta — la más cercana es Productos para la calidad ambiental, en preservación de ecosistemas', 'El Plan Nacional de Negocios Verdes fue diseñado principalmente para productos y servicios que implican una transformación física o un aprovechamiento directo de recursos naturales, mientras que La Mecedora de Darwin ofrece un servicio intangible de comunicación y educación ambiental. Se aproxima a la subcategoría de preservación de ecosistemas porque su labor de divulgación contribuye, de forma indirecta pero central para su misión, a generar conciencia y conocimiento que favorecen la conservación de la biodiversidad del Caribe colombiano.', 'c1',
  '+127% ventas', 'Hoy le vende a la Cruz Roja Colombiana y llegó a la TV nacional.', 'La Mecedora de Darwin es una fundación con sede en Barranquilla dedicada a la divulgación científica y a la comunicación ambiental en la región Caribe. Su actividad consiste en producir contenidos audiovisuales (videos, minidocumentales y animaciones) y en organizar espacios de conversación y talleres presenciales orientados a acercar el conocimiento científico riguroso al público general, con énfasis en la biodiversidad y en el cambio climático. Entre sus productos propios se encuentra “Animania”, una baraja educativa de tipo alfabeto sobre especies animales de América Latina. Sus principales beneficiarios son instituciones educativas, entidades públicas, organizaciones ambientales y empresas con programas de responsabilidad social, así como familias y público general interesado en la ciencia.',
  9933000, 5167333, 11717139,
  '+127%', '["Consolidación de nuevos clientes institucionales: la Cruz Roja Colombiana (Museo del Riesgo MAGMA) y la Institución Universitaria de Barranquilla.", "Adquisición de infraestructura para la producción de contenidos: cámara profesional (Sony ZV-E10 II), micrófonos, disco duro, almacenamiento en la nube y herramientas digitales de edición (Canva, CapCut).", "Consolidación de “Free as Knowledge” como un espacio recurrente de conversación científica, con más de 60 asistentes por evento.", "Diseño de una baraja educativa tipo alfabeto sobre animales latinoamericanos, orientada a la divulgación científica y a la educación ambiental infantil.", "Participación en televisión nacional, formulando preguntas de enfoque ambiental a candidatos presidenciales, con alta visibilidad en redes sociales."]'::jsonb, 'Cifras en promedio mensual (total vendido ene–may 2026: $58.585.696 en 5 meses).', 2, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'soy-de-yuca', 'Soy de Yuca', 'Margarita M. Parra · Fundadora', 'Barranquilla y Soledad',
  'Bioproductos y servicios sostenibles — Agroindustria sostenible', 'El negocio transforma una materia prima agrícola local (yuca) en alimentos de valor agregado mediante procesos de bajo impacto, e incorpora explícitamente prácticas de economía circular (donación de residuos para bioconversión y compostaje), un criterio valorado dentro de la subcategoría de agroindustria sostenible.', 'c4',
  '+95% ventas', 'Dona sus residuos a otros dos beneficiarios: economía circular real.', 'Soy de Yuca es un emprendimiento de agroindustria alimentaria del departamento del Atlántico que transforma la yuca —un tubérculo de alto consumo en la región Caribe colombiana— en productos horneados y congelados listos para preparar, como bollos, tortas y postres, libres de harinas procesadas y de gluten. El negocio atiende dos necesidades a la vez: ofrecer una alternativa alimentaria más saludable frente a los productos ultraprocesados a base de trigo y maíz que dominan el mercado de la costa, y reducir el impacto ambiental de su propia cadena productiva mediante una estrategia de economía circular. Los residuos orgánicos de la elaboración —cáscaras y desechos de yuca— se donan a dos aliados ambientales: OneFly, que los procesa mediante larvas de mosca soldado negro para producir proteína y abono orgánico, y Barcana, que los convierte en compost para huertas urbanas.',
  9955140, 24393000, 47561000,
  '+95%', '["Creación de cinco tablas nutricionales para sus productos, lo que dio mayor formalización técnica a su portafolio.", "Compra de equipos (horno, nevera y congelador) que duplicó la capacidad de producción instalada y mejoró los tiempos de preparación y de almacenamiento.", "Incremento del 25% en las ventas del primer semestre, captando nuevos clientes en Barranquilla sin contar con un punto de venta físico, a través de ferias y visitas comerciales.", "Creación de un nuevo producto en el mes de abril, que amplió la variedad del portafolio y fortaleció la diferenciación frente a la competencia."]'::jsonb, null, 3, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'manteca-de-cerdo', 'Manteca de Cerdo', 'Alicia Ojeda · Fundadora', 'Atlántico',
  'Bioproductos y servicios sostenibles — Agroindustria sostenible', 'El negocio agrega valor a un subproducto de origen animal (la empella) mediante un proceso agroindustrial artesanal ahora formalizado bajo registro INVIMA y Buenas Prácticas de Manufactura, cumpliendo el enfoque de sostenibilidad e inocuidad que define esta subcategoría, y valorizando además un insumo de bajo aprovechamiento comercial dentro de la cadena porcícola.', 'c5',
  '+37% ventas', 'Obtuvo registro INVIMA y multiplicó x5 su capacidad productiva.', 'Cerdos y Más (Inversiones y Soluciones Amicaribe S.A.S.) es una agroindustria artesanal del Atlántico que produce y comercializa manteca de cerdo cien por ciento natural, sin conservantes ni grasas trans, obtenida a partir de la empella, un subproducto de la cadena porcícola local que de otra manera tendría un aprovechamiento comercial limitado. El negocio atiende a restaurantes, panaderías, carnicerías y hogares con tradición culinaria costeña que requieren una grasa natural de alto rendimiento para frituras y repostería, posicionándose como sustituto de aceites vegetales y de grasas industriales ultraprocesadas. Durante el programa, el emprendimiento avanzó de forma significativa en su formalización sanitaria: obtuvo el registro sanitario INVIMA, implementó Buenas Prácticas de Manufactura (BPM) y desarrolló tabla nutricional y etiquetado técnico para sus dos presentaciones comerciales, de 800 gramos en envase plástico y de 900 gramos a 1 kilogramo en envase de vidrio.',
  10000000, 3315800, 4557000,
  '+37%', '["Obtención del registro sanitario INVIMA RSA-4502-2025, que le da legalidad, confianza ante el consumidor y mayor capacidad de comercialización regional y nacional.", "Ampliación de la capacidad productiva con nuevos equipos (mesa en acero inoxidable, lavamanos de pedal, nevera vitrina, fechadora y termómetros, entre otros), que permitió pasar de producir 20 a 100 kilogramos mensuales.", "Desarrollo de tabla nutricional y de etiquetado técnico, junto con la implementación de Buenas Prácticas de Manufactura (BPM).", "Vinculación de nuevos clientes: Pochos Food Company (Petromil), Inspiración BQ Gourmet y Che Carlitos, en presentaciones de 1.800 gramos y 17 kilogramos."]'::jsonb, 'La capacidad productiva instalada pasó de 20 a 100 kg/mes (+400%) con la nueva infraestructura.', 4, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'onefly', 'OneFly', 'Juan Sebastián Garrido · Fundador', 'Barranquilla',
  'Bioproductos y servicios sostenibles — Biotecnología, con un componente adicional de Eco productos industriales — Aprovechamiento de residuos', 'OneFly emplea un bioproceso de transformación de biomasa de insecto para producir un ingrediente proteico y un bioabono (biotecnología), y al mismo tiempo su modelo de negocio central consiste en recibir y valorizar residuos orgánicos de terceros que de otro modo irían a disposición final (aprovechamiento de residuos); por esta razón el emprendimiento se ubica en la intersección de ambas subcategorías.', 'c3',
  'De $0 a ventas', 'Ya procesa 1,6 toneladas de residuos de la Fundación Triple A al mes.', 'OneFly es una empresa de biotecnología ambiental con sede en Barranquilla que resuelve el problema de los residuos orgánicos que hoy terminan en rellenos sanitarios, generando malos olores, líquidos contaminantes y emisiones de gases de efecto invernadero. Su tecnología central es la bioconversión: alimentar residuos orgánicos —provenientes de agroindustrias, supermercados y otros generadores, entre ellos la Fundación Triple A— con larvas de la mosca soldado negro (Hermetia illucens), un insecto cuya larva es capaz de consumir grandes cantidades de materia orgánica y transformarla en biomasa en pocos días. De este proceso se obtienen dos productos: proteína de larva deshidratada, utilizada como insumo para alimento de mascotas y de peces, y “frass”, un residuo sólido rico en nutrientes empleado como abono orgánico. OneFly opera bajo un modelo de negocio doble: cobra a los generadores de residuos por su recolección y procesamiento, y en paralelo vende la proteína y el abono a fabricantes de alimento animal y a productores agrícolas.',
  10000000, 0, 1600000,
  '1.er ingreso', '["Estabilización y estandarización de la producción de huevo de mosca soldado negro a 30 gramos (equivalente al 50% de la capacidad reproductiva de la planta piloto), con revisión cada dos días.", "Rebranding estratégico junto con el proveedor Naiper: nueva imagen comercial y mockups de productos y etiquetas.", "Primera recepción, el 28 de abril de 2026, de 1,6 toneladas de residuos orgánicos de la Fundación Triple A, que se consolida como aliado estratégico de suministro de materia prima.", "Adquisición de estufa, molino y congelador, primera etapa de su propia línea de producción de materia prima.", "Alianza con Canito para la maquila de productos terminados para perros, con miras a nuevos clientes empresariales (B2B).", "Firma de cartas de intención (LOI) para la venta de proteína de larva a clientes de mascotas y de acuicultura en Canadá y en Barranquilla, y de frass a cultivos de rúgula y de limón tahití."]'::jsonb, 'Sin ventas previas comparables — el emprendimiento se encontraba en etapa pre-comercial al ingresar al programa; la cifra corresponde a sus primeras ventas registradas, en consignación.', 5, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'mi-kokito', 'Mi Kokito', 'Liz Karime Blanco · Cofundadora', 'Barranquilla',
  'Bioproductos y servicios sostenibles — Agroindustria sostenible', 'Mi Kokito transforma una materia prima agrícola (el coco) mediante un proceso artesanal de bajo impacto en alimentos de mayor valor agregado y con enfoque en salud, un rasgo característico de la subcategoría de agroindustria sostenible; no se identificó evidencia documental de uso de empaques ecológicos certificados que permita clasificarlo adicionalmente en esa subcategoría.', 'c1',
  '+144% ventas', 'Sus snacks de coco ya están en tres colegios de Barranquilla.', 'Mi Kokito, de marca comercial MICOKITO, es una empresa de alimentos saludables con sede en Barranquilla que procesa coco fresco en planta propia para elaborar snacks diferenciados. Su producto insignia es “BROWNED”, un snack de coco tostado y caramelizado, al que se suma una línea en presentación doypack (bolsa flexible resellable tipo stand-up pouch) y un helado de formato pequeño. Su modelo comercial atiende principalmente a cafeterías escolares y a tiendas saludables, dirigido a familias, estudiantes y niños que buscan alternativas a los snacks ultraprocesados, incluyendo opciones aptas desde el primer año de edad. La relevancia ambiental y social del negocio radica en la sustitución de snacks industrializados por una alternativa de alimentación real y saludable elaborada a partir de un insumo agrícola natural, fomentando hábitos alimentarios más sanos en el entorno escolar.',
  10000000, 12400000, 30280000,
  '+144%', '["Adquisición de maquinaria (peladora de cocos, estibas, olla automatizadora y refrigerador), que redujo el tiempo de pelado de 60 cocos de 4 días a 1 día.", "Ingreso del producto BROWNED a tres colegios de Barranquilla: Marymount, Británico y Alemán.", "Apertura de un nuevo punto de venta, que operó durante un mes y se cerró posteriormente por dificultades operativas con el aliado comercial.", "Alianza comercial en revisión con la distribuidora nacional Tres Veintidós."]'::jsonb, null, 6, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'petfly', 'Petfly', 'Alfonso M. Serje · Fundador', 'Barranquilla',
  'Bioproductos y servicios sostenibles — Biotecnología', 'El producto central de Petfly se basa en un bioproceso de transformación de biomasa de insecto en un ingrediente proteico funcional, una tecnología biológica emergente que sustituye insumos de origen animal convencional; existe además una conexión indirecta con el aprovechamiento de residuos, en la medida en que la cría de esta especie de insecto suele asociarse a la valorización de residuos orgánicos en etapas previas de la cadena de suministro de la proteína.', 'c2',
  '+41% ventas', 'Se expandió a Santa Marta y Cartagena con proteína de insecto.', 'Petfly es una empresa de la costa Caribe dedicada a la formulación y comercialización de suplementos y snacks funcionales para perros elaborados a partir de proteína de mosca soldado negro, en reemplazo de la proteína animal convencional (res o pollo) usada por la mayoría de las marcas de alimento para mascotas. El emprendimiento atiende dos problemas al tiempo: el creciente número de perros con sensibilidades digestivas y alergias alimentarias que no encuentran alternativas confiables en el mercado tradicional, y la huella ambiental de la proteína animal convencional, frente a la cual la proteína de insecto se presenta como una alternativa de menor impacto ecológico. Su producto insignia, “Armadura Digestiva”, es un snack funcional hipoalergénico que no contiene carne y que apoya la salud digestiva y articular de la mascota; a esta línea se suma “Vetfly”, una plataforma tecnológica en desarrollo orientada a personalizar recomendaciones nutricionales. Petfly vende principalmente a clínicas veterinarias y tiendas especializadas de Barranquilla y de la región Caribe.',
  10000000, 6750000, 9550000,
  '+41%', '["Inicio del rediseño del empaque del producto, primera fase de la plataforma Vetfly, y alianza para el desarrollo de nuevas formulaciones (un suplemento tipo topper para el alimento habitual de la mascota).", "Recompra garantizada por parte de tres aliados comerciales (clínicas y tiendas), lo que posiciona la marca en la costa Caribe.", "Expansión a cuatro nuevos puntos de venta, entre ellos Veterinaria El Country, y presencia en Santa Marta y Cartagena.", "Primera contratación de una persona dedicada a impulsar las ventas en punto de venta, utilizando la totalidad del material promocional (POP) disponible.", "Participación en el Congreso Veterinario VEPA, que generó más de 70 contactos comerciales y conexiones con clientes empresariales (B2B)."]'::jsonb, null, 7, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'mar-verde', 'Mar Verde', 'Marjorie Campos · Fundadora', 'Puerto Colombia',
  'Eco productos industriales — Aprovechamiento de residuos', 'La actividad central del negocio es la operación de una Estación de Clasificación y Aprovechamiento que recupera, clasifica y reintroduce a cadenas industriales materiales posconsumo (PET, aluminio, cartón y papel), lo cual corresponde de manera directa a la definición de esta subcategoría del Plan Nacional de Negocios Verdes.', 'c1',
  '+15% ventas', 'Formalizó una red de recicladores en Puerto Colombia.', 'Mar Verde es una organización con sede operativa en Puerto Colombia, Atlántico, dedicada a la gestión formal de residuos sólidos aprovechables mediante la operación de una Estación de Clasificación y Aprovechamiento (ECA), una instalación donde se reciben, separan y clasifican por tipo los materiales reciclables antes de venderlos a la industria. Allí se reciben residuos como plástico PET, aluminio, cartón y papel de archivo, recolectados en hogares, instituciones educativas y empresas, para luego venderlos a transformadores industriales que los reincorporan a nuevas cadenas productivas. El problema que atiende es la persistencia de un sistema de disposición de basuras que mezcla todos los residuos sin separarlos en la fuente, y la existencia de un mercado informal de reciclaje que opera sin trazabilidad ni garantías ambientales; en una zona costera como Puerto Colombia, esto conlleva el riesgo de que materiales reciclables terminen contaminando playas y el mar Caribe. Mar Verde certifica el impacto ambiental de sus usuarios institucionales y empresariales, y trabaja de la mano de la población recicladora de la zona, formalizando y profesionalizando una actividad que tradicionalmente se ha desarrollado en condiciones informales.',
  10000000, 72584677, 83175762,
  '+15%', '["Adquisición de una compactadora, que mejoró la capacidad operativa y los tiempos del proceso de clasificación.", "Aumento en el número de recicladores vinculados a la estación de clasificación.", "Aumento en la frecuencia de venta de materiales PET y aluminio.", "Formalización de un nuevo código de proveedor con Colrecicladora.", "Estudio en curso para la apertura de un nuevo punto de operación en Barranquilla."]'::jsonb, null, 8, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'catleya', 'Catleya', 'Michel Sierra · Fundadora', 'Atlántico',
  'Eco productos industriales — Moda sostenible', 'El proceso productivo emplea fibras naturales e insumos reutilizados como materia prima central de manufactura, en sustitución de textiles sintéticos de origen industrial, y la producción cien por ciento manual y a baja escala reduce el consumo energético frente a la manufactura industrializada de accesorios de moda.', 'c6',
  '+83% ventas', 'Genera empleo directo para cinco mujeres cabeza de hogar.', 'Catleya es un emprendimiento de manufactura artesanal del departamento del Atlántico dedicado a la producción de bolsos y mochilas elaborados completamente a mano por un grupo de mujeres tejedoras, varias de ellas cabezas de hogar, utilizando fibras naturales e hilos y materiales de reúso. El negocio responde a dos problemas al mismo tiempo: la falta de oportunidades de empleo formal para mujeres artesanas de la región, y el impacto ambiental de la industria de accesorios basada en materiales sintéticos y en manufactura mecanizada a gran escala. Al reemplazar procesos industriales por técnica manual y materia prima natural o reutilizada, Catleya reduce la huella ambiental de cada pieza y preserva un oficio artesanal que aporta identidad cultural al territorio. Su mercado objetivo son mujeres de nivel socioeconómico medio-alto y alto sensibles a la moda sostenible y al comercio justo, y su comercialización ocurre principalmente a través de ferias artesanales y de canales digitales.',
  10000000, 4450000, 8149925,
  '+83%', '["Crecimiento sostenido en las ventas de mochilas artesanales (+83%), con mayor aceptación de los diseños y de la calidad del producto.", "Generación de cinco empleos directos para mujeres cabeza de hogar, fortaleciendo su autonomía económica, su estabilidad laboral y sus ingresos.", "Fortalecimiento de la alianza con una comunidad de tejedoras para preservar y promover la técnica manual artesanal.", "Adquisición de maquinaria industrial (máquina de costura y plancha de estampado), que mejoró los tiempos de ensamble y de acabado.", "Implementación de una página web y de un sistema financiero para la gestión integral del emprendimiento."]'::jsonb, null, 9, 'publicado'
);

insert into public.casos_exito
  (slug, company_name, founder_names, municipio, categoria_titulo, categoria_texto, tint,
   badge_text, hito, resumen, inversion, ventas_antes, ventas_actuales, crecimiento_label, hitos, nota, orden, estado)
values (
  'forty-love', 'Forty Love', 'Irene & Shirley Suárez', 'Atlántico',
  'Eco productos industriales — Moda sostenible', 'El uso de textiles certificados internacionalmente, fabricados a partir de plástico reciclado, junto con un modelo de producción limitada por colecciones que reduce el excedente y el desperdicio característico de la moda deportiva de gran escala, ubican a Forty Love directamente en esta subcategoría.', 'c2',
  '+15% ventas', 'Cada prenda reutiliza siete botellas plásticas recicladas.', 'Forty Love es una marca de moda deportiva especializada en indumentaria de tenis para mujer, dirigida a jugadoras aficionadas y profesionales de entre 25 y 55 años que buscan prendas técnicas y de diseño elaboradas bajo criterios de sostenibilidad verificable, en un mercado dominado por marcas masivas y por moda deportiva de bajo costo sin trazabilidad ambiental. El problema que atiende es doble: el alto impacto ambiental de la industria textil convencional, que exige un uso intensivo de agua, de energía y de fibra virgen, y la ausencia de una oferta especializada y con propósito para el tenis femenino. Su respuesta es una colección de ropa deportiva confeccionada con textiles reciclados y certificados internacionalmente, en la que cada prenda equivale, según cifras propias de la marca, al reaprovechamiento de aproximadamente siete botellas plásticas, dándoles una segunda vida y evitando la extracción de fibra virgen. La comercialización es directa, a través de sitio web y de redes sociales, y mediante presencia en torneos y comunidades deportivas, sin intermediarios.',
  10000000, 4800000, 5500000,
  '+15%', '["Diseño de la nueva colección con textiles cien por ciento sostenibles.", "Estandarización de los patrones, moldes y tallas de la nueva colección.", "Producción en curso, próxima al lanzamiento comercial de la colección creada."]'::jsonb, 'Crecimiento calculado sobre un único mes con dato comparable (febrero); la nueva cápsula se encontraba próxima al lanzamiento durante el resto del periodo evaluado.', 10, 'publicado'
